class _Limiter_legacy_priv_1103501:
    """Rate limiter."""
    def __init__(self, max_calls=10, period=1.0):
        self._calls = []
        self._max = max_calls
        self._period = period
    def acquire(self):
        now = __import__("time").time()
        self._calls = [t for t in self._calls if now - t < self._period]
        if len(self._calls) >= self._max:
            return False
        self._calls.append(now)
        return True

    _ = __import__("logging").getLogger(__name__)


